    TwistSquash::SquashKeyA(ALDEBARAN_KEY_B_E_IceLaneA, ALDEBARAN_KEY_B_E_IceLaneB, ALDEBARAN_KEY_B_E_IceLaneC, ALDEBARAN_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

